import { http, HttpResponse } from 'msw';
import { server } from '../setup';
import { fetchWeather } from '../../src/api/weather-api';

describe('api/weather', () => {
  afterEach(() => {
    server.resetHandlers();
  });

  it('returns WeatherData on success', async () => {
